// Anchors — when a task's occurrence falls (tasks-dispatch DESIGN §5).
//
// The arithmetic lives in `calendar.mjs`; this module exposes exactly the two
// questions the queue asks of it — "which occurrence is current" (the scheduler run's
// instantiation guard) and "when does this item wake next" (the roll's stamped
// `Not-before`) — plus the period a frequency repeats on.
//
// Pure and stateless: `now` is always injected, every value is UTC.

import { anchorInstant, normalizeFrequency } from '../calendar.mjs';

const HOUR_MS = 3600e3;
const DAY_MS = 24 * HOUR_MS;

// One period of a frequency, in ms — the unit the janitor's stale-ready rule
// counts in (DESIGN §11) and the coarse step `nextAnchor` walks.
export function periodMs(frequency) {
  // Normalized like `anchorInstant`. Today this changes no answer — every retired token maps to
  // `daily`, which is also the fallthrough below — so it is insurance, not the thing carrying the
  // behaviour: it is what keeps this correct if `LEGACY_FREQUENCIES` ever gains a mapping that is
  // not `daily`. What DOES carry it is the door plus that fallthrough, and why it matters is
  // sharp: this feeds the janitor's stale-ready bound and the precondition's signal window, so a
  // token resolving to an HOUR here parks a member's task needs-human on every sweep (§17.1).
  const freq = normalizeFrequency(frequency);
  if (freq === 'weekly') return 7 * DAY_MS;
  if (freq === 'monthly') return 31 * DAY_MS;
  if (freq === 'manual') return null;
  return DAY_MS;
}

// The most recent occurrence at or before `now`, as a Date. `manual` has none —
// the scheduler run never instantiates it (DESIGN §8), so null is the whole answer.
export const mostRecentAnchor = anchorInstant;

// The earliest occurrence strictly after `now` — what a rolled item is stamped
// with. Derived by walking `mostRecentAnchor` forward rather than by adding a
// period: monthly anchors are not a fixed distance apart, and a `daily-2h` whose
// instant wraps to the previous calendar day is exactly the case a fixed add gets
// wrong. The coarse step is under one period, so the loop advances by at most two
// steps and never overshoots an occurrence.
export function nextAnchor(frequency, schedule, now) {
  if (normalizeFrequency(frequency) === 'manual') return null;
  const from = mostRecentAnchor(frequency, schedule, now).getTime();
  const step = normalizeFrequency(frequency) === 'monthly' ? 28 * DAY_MS : periodMs(frequency);
  for (let t = from + step; ; t += step) {
    const candidate = mostRecentAnchor(frequency, schedule, new Date(t));
    if (candidate.getTime() > from) return candidate;
  }
}
// The schedule board (tasks-dispatch DESIGN §5, decision §15.28) — one open
// issue per repo, `[claudinite-schedule]`, whose body is a table with one row
// per scheduled task: the anchor it was last asked at, the verdict it gave and
// why. The scheduler run reads it as the watermark ("have I already asked this
// task about this occurrence?") and rewrites it only when a row changes.
//
// Parse/serialize of the board lives here and nowhere else, the way
// work-item.mjs owns the work item's schema. The board is a FIRST authority
// only for "asked at anchor A, declined"; frequency and the next window are
// derived from the declarations and `anchors.mjs` and re-rendered at every
// write. Durability is deliberately weak: a deleted, mangled or unreadable
// board degrades to "absent" per-row and costs one redundant evaluation —
// it fails toward evaluating, never toward skipping.
//
// The title prefix is disjoint from `[claudinite-work]` and `[claudinite-task]`
// on purpose: the board must never parse as a work item (the scheduler run's
// title-exact family match, `listOpenWorkItems`, the janitor) and never read
// as repo activity (the `issues` signal collector excludes all three prefixes).

import { nextAnchor } from './anchors.mjs';

export const SCHEDULE_PREFIX = '[claudinite-schedule]';

export const scheduleBoardTitle = () => `${SCHEDULE_PREFIX} the schedule board`;

export const isScheduleBoardTitle = (title) => String(title ?? '').startsWith(SCHEDULE_PREFIX);

// The verdict vocabulary a row may carry. Anything else parses as itself (a
// future writer's word must not break this reader) but only `no` ever gates:
// the watermark is scoped to declined rows (F31) — a `go` or `fail-open`
// verdict's cover is the item it created, and a go row honored as a gate
// would eat the occurrence whenever the item's own create failed after the
// row landed.
export const VERDICT_NO = 'no';
export const VERDICT_GO = 'go';
export const VERDICT_FAIL_OPEN = 'fail-open';

// ~64KB is the platform's issue-body cap; stay well under it so the write can
// never 422. Trivial at ~25 rows, budgeted anyway per the two-tier rule.
const BODY_BUDGET = 60_000;
const REASON_MAX = 160;

const cell = (s) => String(s ?? '').replace(/\|/g, '\\|').replace(/\s+/g, ' ').trim();
const clip = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);

// Render the whole board body from rows ({ task, frequency, lastAsked,
// verdict, reason }). `schedule` and `now` feed the derived next-window
// column, recomputed at every write — it is display, never data, which is why
// a stale one on a quiet row is harmless and why the change test upstream
// compares only the authoritative columns.
export function renderScheduleBoard(rows, { now = new Date(), schedule = null } = {}) {
  const sorted = [...rows].sort((a, b) => (a.task < b.task ? -1 : a.task > b.task ? 1 : 0));
  const header = [
    'One row per scheduled task: the anchor it was last asked at, the verdict, and why.',
    'The scheduler run reads this as its watermark — a declined occurrence is re-asked only at the task\'s next anchor — and files a work item only when a precondition says yes.',
    'Machine-maintained; edits are overwritten on the next change. Deleting this issue costs one redundant evaluation per task and nothing else.',
    '',
    '| task | frequency | last asked | verdict | reason | next window |',
    '|---|---|---|---|---|---|',
  ];
  const line = (r, reasonMax) => {
    let next = '';
    try {
      const n = r.frequency && r.frequency !== 'manual' && schedule !== undefined
        ? nextAnchor(r.frequency, schedule, now) : null;
      next = n ? n.toISOString() : '';
    } catch { next = ''; }
    return `| ${cell(r.task)} | ${cell(r.frequency)} | ${cell(r.lastAsked)} | ${cell(r.verdict)} | ${clip(cell(r.reason), reasonMax)} | ${next} |`;
  };
  const full = [...header, ...sorted.map((r) => line(r, REASON_MAX))].join('\n') + '\n';
  if (full.length <= BODY_BUDGET) return full;
  // Compact tier: every row survives with its reason dropped; rows that still
  // do not fit are counted rather than silently lost.
  const kept = [];
  let used = header.join('\n').length + 200; // slack for the omitted-count line
  for (const r of sorted) {
    const l = line(r, 0);
    if (used + l.length + 1 > BODY_BUDGET) break;
    kept.push(l);
    used += l.length + 1;
  }
  const omitted = sorted.length - kept.length;
  return [...header, ...kept,
    ...(omitted ? ['', `…and ${omitted} more row(s) omitted for size.`] : [])].join('\n') + '\n';
}

// Parse a board body back into rows. Tolerant per-row: a line that does not
// parse is simply skipped — a mangled row reads as absent for its task, which
// costs one redundant evaluation and nothing else. Never throws.
export function parseScheduleBoard(body) {
  const rows = new Map();
  for (const l of String(body ?? '').split('\n')) {
    const line = l.trim();
    if (!line.startsWith('|')) continue;
    const cells = line.split(/(?<!\\)\|/).slice(1, -1).map((c) => c.replace(/\\\|/g, '|').trim());
    if (cells.length < 5) continue;
    const [task, frequency, lastAsked, verdict, reason] = cells;
    if (!task || task === 'task' || /^-+$/.test(task)) continue; // header/separator
    if (!/^\S+\/\S+$/.test(task)) continue;
    rows.set(task, { task, frequency: frequency || null, lastAsked: lastAsked || null, verdict: verdict || null, reason: reason ?? '' });
  }
  return rows;
}

// The board issue, found by its exact title prefix over the OPEN issues list
// (the same REST-not-search rule as the work-item reads, S6/F11). More than
// one open board — a hand-created duplicate, or a torn create — resolves to
// the OLDEST, deterministically, so every run converges on the same one.
// A list that cannot be read answers `readable: false`: the caller evaluates
// fail-open AND skips the board write — never write what you could not read.
export async function findScheduleBoard(gh, repo) {
  for (let page = 1; ; page += 1) {
    const { status, json } = await gh(`/repos/${repo}/issues?state=open&sort=created&direction=asc&per_page=100&page=${page}`);
    if (status !== 200 || !Array.isArray(json)) return { readable: false, issue: null };
    for (const i of json) {
      if (i.pull_request) continue;
      if (isScheduleBoardTitle(i.title)) return { readable: true, issue: { number: i.number, body: i.body ?? '' } };
    }
    if (json.length < 100) return { readable: true, issue: null };
  }
}
// COMPATIBILITY ENTRY POINT — "the tick" was renamed to the scheduler run (#877),
// and the mechanism now lives in `scheduler-run.mjs` beside this file. Nothing in
// the canon imports this path.
//
// WHY IT MUST EXIST. A member's `.github/workflows/claudinite-scheduler.yml` names
// the module it runs as a literal path, and that file is the ONE path a converge
// cannot push: it lands as a pull request the member has to merge, on its own
// cycle, while the mount beside it refreshes nightly. So every member spends a
// window running the new mount from an old workflow — and a workflow whose
// `node .claudinite/shared/packs/claudinite-tasks/queue/tick.mjs` finds nothing is a
// repo whose whole queue stops, silently, with no run left to fix it.
//
// WHEN IT GOES. When no member's `.github/workflows/claudinite-scheduler.yml`
// still names this path — read the members' workflow files, do not guess a date.

import { runSchedulerRun } from './scheduler-run.mjs';

console.log('- invoked as `tick.mjs`, which is the old name for the scheduler run —'
  + ' this repo\'s scheduler workflow is behind the mount and should be re-converged');
runSchedulerRun().catch((e) => { console.error(e); process.exit(1); });
// WHEN A BLOCKED ITEM MAY RUN (tasks-dispatch DESIGN §9, decision §15.19,
// reversed by decision §15.31 / #1373). One caller asks this question: the
// scheduler run, hourly, over every open item. A close does not — releasing a
// dependent is deciding whether the world has moved on, which is what the
// scheduler run exists to re-derive, and a task execution converging its own
// item has no business relabelling a sibling work item to answer it.
//
// The backstop framing survives the reversal unchanged: nothing but the
// scheduler run's hourly pass ever releases a blocked item, so a chain link
// waits at most one scheduler run for its dependency to be noticed.

import { STATUS_BLOCKED, isStatus, parseWorkItemBody } from './work-item.mjs';

// Is this item's wait over? `stateOf(n)` answers the state of a `Blocked-by`
// target that may not be a work item at all — an unknown number is never treated
// as closed, so an unreadable blocker DELAYS rather than releases (the
// convergence-not-prevention posture). An item in triage is nobody's to release.
export function isReleasable(item, { stateOf = () => null, nowMs = Date.now() } = {}) {
  if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED)) return false;
  const { notBefore, blockedBy } = parseWorkItemBody(item.body);
  const blockersDone = blockedBy.every((n) => stateOf(n) === 'closed');
  const timeReached = notBefore === null || nowMs >= new Date(notBefore).getTime();
  return blockersDone && timeReached;
}
// THE DEFAULTS, and the one place a declaration's absent field becomes a value,
// so nothing downstream ever reads an undefined one (owner, 2026-09-03):
//   - `preconditions`: run always — `['none']`.
//   - `automerge`: land nothing unreviewed — `'nothing'`, for a task that may open a PR.
//   - `agent_model`: no agent — `'none'`.
//   - `code_work`: no code work; `agent_instructions`: none.
// Neither timeout has a default, deliberately: an agent or a code-work
// subprocess always carries its own time limit, so the field is required
// wherever the phase it bounds is declared. `frequency` and `expected_outcome`
// have no default either — each is a choice the author makes.
// A task that declares a field keeps it; only an absent one is filled.
export const DEFAULT_PRECONDITIONS = ['none'];
export const DEFAULT_AUTOMERGE = 'nothing';
export const DEFAULT_AGENT_MODEL = 'none';

// Fill the absent fields in place and return the declaration.
export function applyTaskDefaults(out) {
  if (out.preconditions === undefined) out.preconditions = [...DEFAULT_PRECONDITIONS];
  if (out.agent_model === undefined) out.agent_model = DEFAULT_AGENT_MODEL;
  if (out.expected_outcome === 'pr' && out.automerge === undefined) out.automerge = DEFAULT_AUTOMERGE;
  return out;
}
// Loading a task's OWN precondition terms — the extension mechanism the built-in
// vocabulary leaves room for (task-preconditions DESIGN, "The term vocabulary").
// A task whose gate is its own (an age against a configured retention, a manifest
// against a release tag, a fleet read) ships `preconditions.mjs` beside its
// `task.json`, exporting `terms`: a map from term name to
// `{ signals, takesArg?, holds(signals, opts) }`. The term's code then lives
// beside its only consumer, so reading the declaration and reading the gate are
// one directory apart.
//
// Split from precondition-policy.mjs, which stays pure over the signals: this is
// the half that touches the filesystem, and the evaluator is handed the result.

import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { termsMap } from './precondition-policy.mjs';

export const TASK_TERMS_FILE = 'preconditions.mjs';

// The terms a task directory contributes — an empty map when it ships no file.
// A file that will not import THROWS: the caller (discovery, dispatch
// validation) reports the task as broken, which is the loud direction. A task
// whose gate cannot be loaded must not fall back to running unconditionally.
export async function loadTaskTerms(taskDir) {
  const file = join(taskDir, TASK_TERMS_FILE);
  if (!existsSync(file)) return new Map();
  return termsMap((await import(pathToFileURL(file).href)).terms);
}
// COMPATIBILITY SHIM — not a module anything should import today. The calendar
// lives in `calendar.mjs`; this path exists so a member carrying an OLD pack keeps
// loading after the engine has moved on.
//
// WHY IT MUST EXIST. The engine lane and the pack lane deliver in separate PRs on
// separate cycles, and pack delivery is version-gated per pack — so every member
// passes through a window holding the NEW engine beside an OLD pack, and nothing
// can close that window. A pack file importing an engine module is therefore a
// stale caller of an instantly-current engine, the same asymmetry `updates/*`
// already carries ("empty an export, never remove it"). Renaming this module
// without leaving the shim broke exactly that way (#1004): a pack that fails to
// load fails the mount's self-test, the converge then refuses to land AT ALL, and
// the member cannot even receive the pack version that would have fixed it.
//
// WHAT IS HERE. Only what a fielded pack version actually imports — re-exported,
// never re-declared, so the shim cannot drift from the module it stands in for.
// WHICH imports those are is a fact about the versions members are carrying, so it
// is derived from history by `packs/claudinite-tasks/test/engine-pack-lane-shims.test.mjs`
// rather than listed here, where it would go stale silently.
//
// WHEN IT GOES. When no member's stamped `packVersions` names a version that still
// imports this path — read the field, do not guess a release.
export { FREQUENCIES } from './calendar.mjs';

