360	      model: asked.model,
361	      blockedBy,
362	      notBefore,
363	      merge: asked.merge,
364	      ungated: asked.ungated,
365	      // Origins are for life (§3), so an issue marked with the retired spelling gains
366	      // the one it will be read by. Nothing removes the old label: it is stored data.
367	      origin: hasLabel(req, ORIGIN_AD_HOC) ? null : ORIGIN_AD_HOC,
