371	  // ---- job 3: reclaim dead executor claims (DESIGN §11) -------------------
372	  const policyOf = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t.decl.on_interrupt ?? 'requeue']));
373	  for (const item of items) {
374	    if (item.state !== 'open' || !isStatus(item, STATUS_RUNNING_EXECUTOR)) continue;
375	    // SILENCE IS THE HOLDER'S, not the issue's (§11, #924). `updated_at` moves on
376	    // any comment — including the one an executor that LOST the claim race writes
377	    // on its way out — which defers the reclaim of an item nobody is working on.
378	    // `livenessAt` is the shell's read of the holder's last claim or heartbeat;
