380	    // the pre-heartbeat behaviour and errs toward waiting.
381	    const lastSign = ms(item.livenessAt) ?? ms(item.updated_at) ?? ms(item.created_at) ?? nowMs;
382	    const silentFor = nowMs - lastSign;
383	    if (silentFor < executingLeashMs) continue;
