396	      // ONE label either way: back into the queue, or parked at the kind that says
397	      // what the human is being asked for — whether the interrupted run left
398	      // anything behind, and so whether this re-queues at all.
399	      kind: 'reclaim', issue: item.number, to: oneShot ? NEEDS_HUMAN_DECISION : READY,
400	      reason: oneShot
