406	  // ---- the board write, LAST and only on change ---------------------------
407	  // A run that moved no row writes nothing — record changes, never scans —
408	  // and the board is created lazily: the first row that needs writing is
409	  // what mints the issue.
410	  if (boardChanged) ops.push({ kind: 'board', rows: [...boardRows.values()] });
