415	// --- the forced wake (DESIGN §8) ----------------------------------------------
416	
417	// Which standing items a `wake` dispatch names. Forcing a scheduled task IS waking
418	// its standing item, and this is that same lever reached from OUTSIDE the repo: the
419	// fleet enforcer dispatches this workflow with the task ids it wants run now, and
420	// the member wakes its own items with its own token. The enforcer therefore needs
421	// no issue access anywhere — the fan-out model the enforcer's sweeps are built on, where
422	// the enforcer dispatches and the member executes.
423	//
424	// An id is `pack/task` or a bare `task` resolved against this repo's own discovered
425	// tasks, so a caller spanning many members never has to know any one member's pack
426	// layout. Every id that matches nothing comes back in `unmatched`: a force whose
427	// report counts only what it woke reads as coverage it did not have.
428	//
429	// An item already in flight (`task:ready`, `task:executing`, `task:agent`) is left
430	// alone and reported as `already`, never re-woken — an episode boundary dropped on
431	// a live claim is exactly the livelock F18 describes.
432	//
433	// WHEN THE STANDING ITEM DOES NOT EXIST, forcing MINTS it (§8's other lever). A
434	// task that completes closes its item, and the next one appears only at the next
435	// anchor — so between the two there is nothing to wake, and that gap is the common
436	// case rather than an edge: a daily task is missing its item for most of the day.
437	// A force that reported "nothing to wake" there would fail on most members most of
438	// the time, which is precisely what a fleet-wide converge lever must not do. The
439	// minted item is an ordinary standing item — same title, no qualifier: it consumes
440	// the CURRENT occurrence, so the scheduler run does not then create a second one beside it,
441	// and it leaves the next anchor's occurrence untouched.
442	export function planWake(spec, tasks = [], items = []) {
443	  const ids = String(spec ?? '').split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
444	  const wake = []; const create = []; const already = []; const unmatched = [];
445	  for (const id of ids) {
446	    const [a, b] = id.includes('/') ? id.split('/') : [null, id];
447	    const owners = tasks.filter((t) => t.id === b && (a === null || t.pack === a));
448	    if (owners.length !== 1) {
449	      unmatched.push({ id, why: owners.length ? `${owners.length} declared packs own a "${b}" task — name it as pack/task` : 'no declared pack owns a task by that name' });
450	      continue;
451	    }
452	    const owner = owners[0];
453	    const { pack, id: task } = owner;
454	    const item = items.find((i) => {
455	      if (i.state !== 'open') return false;
456	      const parsed = parseWorkItemTitle(i.title);
457	      return parsed && parsed.pack === pack && parsed.task === task;
458	    });
459	    if (!item) { create.push({ id: `${pack}/${task}`, pack, task, taskPath: owner.taskPath }); continue; }
460	    if (IN_FLIGHT.includes(statusOf(item))) { already.push({ id, issue: item.number }); continue; }
461	    wake.push({ id: `${pack}/${task}`, issue: item.number });
462	  }
463	  return { wake, create, already, unmatched };
464	}
