466	// The Context a forced standing item carries. It says the force is the only reason
467	// the item exists, because the executor still evaluates the precondition at pick:
468	// a force that finds no work must roll with its reason on record, not invent work.
469	export const FORCED_WAKE_CONTEXT =
470	  'Minted by a force — this task had no open standing item at the time. The precondition is still evaluated at pick, so converge to a no-op if there is nothing to do.';
471	
472	// The statuses that mean someone already holds this item — decoded, so an item any
473	// engine version filed answers the same. `running-agent` counts: the work is with a
474	// session, and waking would hand a second executor the same item.
475	const IN_FLIGHT = [STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT];
