477	// --- CLI: the thin I/O shell the vendored scheduler run workflow invokes ---------------
478	// Reads the work-item list, plans, applies. All GitHub access is the Action's
479	// GITHUB_TOKEN. Dormancy is the first gate, before any read — a project that has
480	// said it is out of the recurring work should not pay for the list that proves it.
481	
482	// Every WORK ITEM, state=all, via the ISSUES list API — never the search index
483	// (S6/F11: search is eventually consistent, and a family list that misses a
484	// just-created item mints a duplicate standing item). Bounded by the scheduled
485	// families' need for closed history: closed items are only interesting back to the
486	// widest period, so the listing stops once it is past that.
487	//
488	// MEMBERSHIP IS `isQueueItem`, the shared predicate, and not the title prefix
489	// (#1497). An adopted marked issue IS an item under the one-issue model (DESIGN
490	// §16.1) and keeps the person's own title forever, so a prefix test drops exactly
491	// that class — and job 2 is the ONLY site that releases a blocked item, so an
492	// ad-hoc item born blocked on a `Not-before:` sat sleeping past its instant with
493	// nothing left to wake it (#1267, #1349, #1351, #1396). The executor and the
494	// janitor already read the queue through this predicate; this list was the one that
495	// did not.
496	export async function listWorkItems(gh, repo, { since = null } = {}) {
497	  const out = [];
498	  for (let page = 1; ; page += 1) {
499	    const q = `state=all&sort=created&direction=desc&per_page=100&page=${page}`
500	      + (since ? `&since=${encodeURIComponent(since)}` : '');
501	    const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
502	    // A page that could not be read is not the end of the list. Breaking on it
503	    // truncates the queue mid-pagination and the run plans against the remainder:
504	    // a standing item whose page never arrived reads as absent, and the run mints a
505	    // second one beside it.
506	    if (status !== 200 || !Array.isArray(json)) {
507	      throw new Error(`could not list work items in ${repo} at page ${page} (${status}) — a truncated queue is not a shorter one`);
508	    }
509	    if (json.length === 0) break;
510	    for (const i of json) {
511	      if (i.pull_request) continue;
512	      if (!isQueueItem(i)) continue;
513	      out.push({
514	        number: i.number, title: i.title, body: i.body ?? '', state: i.state,
515	        labels: labelNames(i), created_at: i.created_at, closed_at: i.closed_at,
516	        updated_at: i.updated_at,
517	      });
518	    }
519	    if (json.length < 100) break;
520	  }
521	  return out;
522	}
