524	// Every OPEN issue carrying the mark and NO status, via the ISSUES list API
525	// filtered by label — never the search index, for the same reason the work-item
526	// list is not (S6/F11): a mark this list misses is a request that silently waits an
527	// hour, and one it misses TWICE is a request nobody notices was never picked up.
528	//
529	// The author's push permission comes back with each issue, because adoption gates
530	// the body's parameters on it (§16.7) and the payload's `author_association` is not
531	// that fact: `MEMBER` is any org member whatever their repo permission, and
532	// `COLLABORATOR` includes read-only collaborators (F30). A read that cannot answer
533	// leaves the flag `null`, which gates the parameters off — the safe end of a field
534	// that chooses a task, a model, or the right to land a change without review.
535	export async function listMarkedIssues(gh, repo, { permissionOf = null } = {}) {
536	  const out = [];
537	  const push = permissionOf ?? (async (login) => {
538	    const res = await gh(`/repos/${repo}/collaborators/${encodeURIComponent(login)}/permission`);
539	    if (res.status === 404) return false;
540	    if (res.status !== 200) return null;
541	    return ['admin', 'maintain', 'write'].includes(res.json?.role_name ?? res.json?.permission ?? 'none');
542	  });
543	  const cache = new Map();
544	  // ONE QUERY PER MARK, unioned here. GitHub's `labels` filter is CONJUNCTIVE — a
545	  // comma-separated list selects the issues carrying EVERY name on it — so asking
546	  // for both marks at once asks for issues wearing both, which nothing does. The
547	  // retired `claude-task` spelling keeps working for whoever has it in muscle memory
548	  // or in a template, decoded forever like every legacy spelling (§4), and that
549	  // costs a second listing rather than a wider one.
550	  const seen = new Map();
551	  for (const label of [ORIGIN_AD_HOC, REQUEST_LABEL]) {
552	    for (let page = 1; ; page += 1) {
553	      const q = `state=open&labels=${encodeURIComponent(label)}&per_page=100&page=${page}`;
554	      const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
555	      // A list that could not be READ is not a list that is EMPTY, and the two are
556	      // indistinguishable downstream: adoption simply finds nothing to do and the run
557	      // reports success. Every request then waits for a person to notice, which is
558	      // the one thing this lane exists so nobody has to do.
559	      if (status !== 200 || !Array.isArray(json)) {
560	        throw new Error(`could not list open issues marked \`${label}\` in ${repo} (${status}) — an unreadable request list is not an empty one`);
561	      }
562	      if (json.length === 0) break;
563	      for (const i of json) {
564	        if (i.pull_request) continue;
565	        // A filed work item wearing the mark is not a request awaiting adoption: it is
566	        // already an item, and re-adopting one would rewrite its body under the run
567	        // holding it.
568	        if ((i.title ?? '').startsWith(WORK_PREFIX)) continue;
569	        // ANY status means this mark has been adopted — the exactly-once guard (§16.3).
570	        // Filtering here rather than in the plan keeps the permission reads to the
571	        // issues actually awaiting adoption.
572	        if (statusOf(i) !== null) continue;
573	        // An issue wearing both spellings comes back from both listings; it is one
574	        // request, and adopting it twice would rewrite the body of the item the first
575	        // adoption just made.
576	        if (seen.has(i.number)) continue;
577	        const author = i.user?.login ?? null;
578	        if (author && !cache.has(author)) cache.set(author, await push(author));
579	        seen.set(i.number, {
580	          number: i.number, title: i.title, body: i.body ?? '', state: i.state,
581	          labels: labelNames(i), author, authorHasPush: author ? cache.get(author) : null,
582	        });
583	      }
584	      if (json.length < 100) break;
585	    }
586	  }
587	  out.push(...seen.values());
588	  return out;
589	}
