591	// Which `Blocked-by` targets this run still has to read. A target need not be a
592	// work item — a fan-in blocks on whatever its children are — so states come from
593	// the fetched items first and a direct read otherwise, and `known` is what has
594	// already been answered.
595	//
596	// A marked issue's blockers count the same way: adoption decides whether the item
597	// it births is born blocked or ready, and an unread state is never `closed`, so a
598	// missing read delays the request rather than releasing it (§16.11).
599	//
600	// Extracted from `main` so it can be called at all. Nothing else here drives
601	// `main`, whose body is I/O against a live Action, so an identifier it names and
602	// never imports resolves at run time or not at all — and the request half went
603	// three days without executing once, behind an adoption list that was always
604	// empty (#1354).
605	export function blockersToResolve(items, requests, known) {
606	  const wanted = new Set();
607	  for (const i of items) {
608	    if (i.state !== 'open' || !isStatus(i, STATUS_BLOCKED)) continue;
609	    for (const n of parseWorkItemBody(i.body).blockedBy) if (!known.has(n)) wanted.add(n);
610	  }
611	  for (const r of requests) {
612	    for (const n of parseBlockedBy(r.body)) if (!known.has(n)) wanted.add(n);
613	  }
614	  return wanted;
615	}
