757	        `Queued: a run of \`${op.task}\` for this issue${op.model ? `, at the \`${op.model}\` family` : ''}.\n\n`
758	        + (op.blockedBy.length
759	          ? `It is **blocked** on ${op.blockedBy.map((n) => `#${n}`).join(', ')} — it enters the queue once they close.\n\n`
760	          : '')
761	        + (op.notBefore ? `It waits until ${op.notBefore} before entering the queue.\n\n` : '')
762	        + (op.merge
763	          ? `The run implements this issue and opens a pull request; it may land that pull request itself only when the diff sits inside the authorized policy (\`${op.merge}\`), and leaves a wider one for review. `
764	          : 'The run implements this issue and opens a pull request for review — it never merges one. ')
765	        + (op.ungated
766	          ? '\n\nThe `Task:`/`Model:`/`Automerge:` fields in this body were ignored: they are honoured only for an author with push access on this repository, so this run takes the defaults. '
767	          : '')
768	        + `To withdraw the request before it starts, remove the \`${ORIGIN_AD_HOC}\` mark and the status beside it.`);
769	      console.log(`- adopted #${op.request} for ${op.task} (${op.model ?? 'default model'}${op.blockedBy.length ? `, blocked on ${op.blockedBy.map((n) => `#${n}`).join(' ')}` : ''}${op.merge ? `, may merge: ${op.merge}` : ''})`);
770	    } else if (op.kind === 'supersede') {
771	      await comment(gh, repo, op.issue, op.reason);
772	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
773	      await closeIssue(gh, repo, op.issue, 'not_planned');
774	      console.log(`- superseded #${op.issue} — #${op.request} was re-marked`);
775	    } else if (op.kind === 'dedupe') {
776	      await comment(gh, repo, op.issue, op.reason);
777	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
778	      await closeIssue(gh, repo, op.issue, 'not_planned');
779	      console.log(`- deduped #${op.issue}`);
780	    } else if (op.kind === 'retire-orphan') {
781	      await comment(gh, repo, op.issue, op.reason);
782	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
783	      await closeIssue(gh, repo, op.issue, 'not_planned');
784	      console.log(`- reaped #${op.issue} — ${op.pack}/${op.task} is not declared at HEAD`);
785	    } else if (op.kind === 'retire-sleeping') {
786	      await comment(gh, repo, op.issue, op.reason);
787	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
788	      await closeIssue(gh, repo, op.issue, 'not_planned');
789	      console.log(`- retired sleeping item #${op.issue} ${op.pack}/${op.task} onto the schedule board`);
790	    } else if (op.kind === 'board') {
791	      if (!boardFetch.readable) {
792	        // Never write what could not be read: a blind create could mint a
793	        // second board. The rows this run derived are re-derived next run.
794	        console.log('! the schedule board could not be listed — skipping its rewrite this run');
795	      } else if (boardFetch.issue) {
796	        const res = await gh(`/repos/${repo}/issues/${boardFetch.issue.number}`, {
797	          method: 'PATCH',
798	          body: { body: renderScheduleBoard(op.rows, { now, schedule: config.taskScheduler }) },
799	        });
800	        console.log(res.status === 200
801	          ? `- schedule board #${boardFetch.issue.number} updated (${op.rows.length} row(s))`
802	          : `! could not update schedule board #${boardFetch.issue.number}: ${res.status}`);
803	      } else {
804	        const res = await createIssue(gh, repo, {
805	          title: scheduleBoardTitle(),
806	          body: renderScheduleBoard(op.rows, { now, schedule: config.taskScheduler }),
807	          labels: [],
808	        });
809	        console.log(res.number
810	          ? `- schedule board created as #${res.number} (${op.rows.length} row(s))`
811	          : `! could not create the schedule board: ${res.status}`);
812	      }
813	    }
814	  }
815	
816	  if (!ops.length) console.log('- nothing to do: every task has its standing item, nothing is due, nothing is marked, no claim is dead');
817	
818	  // The forced wake, last: an item this run just instantiated is wakeable in the
819	  // same run, so a force never has to be pressed twice. The drain job that follows
820	  // picks up whatever this readies.
821	  const spec = process.env.CLAUDINITE_WAKE ?? '';
822	  if (spec.trim()) {
823	    const { wakeItem } = await import('./create-work-item.mjs');
824	    // Re-read: the ops above may have created or readied the very items named.
825	    const current = await listWorkItems(gh, repo, { since });
826	    const { wake, create, already, unmatched } = planWake(spec, tasks, current);
827	    for (const w of wake) {
828	      const res = await wakeItem(gh, repo, w.issue);
829	      if (res.ok) readied.add(w.issue);
830	      console.log(res.ok ? `- woke #${w.issue} ${w.id}` : `! could not wake #${w.issue} ${w.id}: ${res.error}`);
831	    }
832	    if (create.length) await ensureLabels(gh, repo, QUEUE_LABELS);
833	    for (const c of create) {
834	      const res = await createIssue(gh, repo, {
835	        title: workItemTitle({ pack: c.pack, task: c.task }),
836	        body: workItemBody({ taskPath: c.taskPath, context: [FORCED_WAKE_CONTEXT] }),
837	        // A forced mint stands in for the occurrence a schedule would have filed, so
838	        // it wears the same origin: the task IS on a calendar, and this item is its
839	        // current occurrence (§8).
840	        labels: [ORIGIN_PLANNED, READY],
841	      });
842	      if (res.number) {
843	        readied.add(res.number);
844	        console.log(`- created #${res.number} ${c.id} (forced: it had no open standing item)`);
845	      } else { console.log(`! could not create a work item for ${c.id}: ${res.status}`); process.exitCode = 1; }
846	    }
847	    for (const a of already) console.log(`- ${a.id} is already in flight on #${a.issue} — left alone`);
848	    for (const u of unmatched) console.log(`! nothing woken for "${u.id}": ${u.why}`);
849	    // A force that woke nothing is a failed force, and a green run saying so in a
850	    // log line is how it goes unnoticed by the fleet lever that pressed it.
851	    if (unmatched.length) process.exitCode = 1;
852	  }
853	
854	  // LAST, AFTER THE WAKE: whether this run leaves anything for an executor to do.
855	  await announcePickable(gh, repo, tasks, readied);
856	}
857	
858	// THE DRAIN GATE (§15.30). Every workflow run is a billed invocation whatever it
859	// finds — Actions rounds each job's minutes up — so the drain job dispatches an
860	// executor only when this run's parting look at the queue found something
861	// pickable. On a quiet repo that is the difference between 24 executor runs a day
862	// and none.
863	//
864	// This is the run's LAST act, after the forced wake: a wake readies items, and a
865	// look taken before it would send the hour's forced work to the next cron fire.
866	//
867	// The delivery is unweakened by the gate. A label event may be lost, and what a
868	// lost event would have delivered is exactly what this look sees — the queue
869	// itself, read live, by the same pick rule the executor applies. Where the
870	// output cannot be written (a run outside Actions, an older member workflow that
871	// maps no output) the drain job's own default decides, and the run says which
872	// happened rather than going quiet about it.
873	// THE VERDICT IS A UNION, not a read. What the list returns is one source; what
874	// this run itself readied is the other, and the second needs no confirmation —
875	// GitHub's issue list is eventually consistent, so an item created milliseconds
876	// earlier can be absent from it (#1340). Trusting the read alone left a forced
877	// `update` sitting `task:ready` until the next cron fire on three members at once.
878	// Ordering stays the executor's job: this only decides whether to start one.
879	export function pickableCount(open, readiedThisRun = [], opts = {}) {
880	  const listed = pickOrder(open, opts).map((i) => i.number);
881	  return new Set([...listed, ...readiedThisRun]).size;
882	}
883	
884	async function announcePickable(gh, repo, tasks, readiedThisRun = new Set()) {
885	  const { listOpenWorkItems } = await import('./read.mjs');
886	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
887	  const byPath = new Map(tasks.map((t) => [t.taskPath, `${t.pack}/${t.id}`]));
888	  const pickable = pickableCount(await listOpenWorkItems(gh, repo), readiedThisRun, {
889	    taskAfter: (id) => byId.get(id)?.decl?.schedule_after ?? [],
890	    frequencyOf: (id) => byId.get(id)?.decl?.frequency ?? null,
891	    pathTo: (p) => byPath.get(p) ?? null,
892	  });
893	  console.log(pickable
894	    ? `- ${pickable} item(s) pickable — the drain job dispatches an executor`
895	    : '- nothing pickable — no executor is dispatched this run');
896	  const out = process.env.GITHUB_OUTPUT;
897	  if (!out) return;
898	  const { appendFileSync } = await import('node:fs');
899	  appendFileSync(out, `pickable=${pickable ? 'true' : 'false'}\n`);
900	}
901	
902	// Run only when invoked directly (the workflow's `node scheduler-run.mjs`), never on
903	// import. Exported as well, because `tick.mjs` beside this file is a fielded entry
904	// point that must be able to start the same run without being this module.
905	export { main as runSchedulerRun };
906	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
907	  main().catch((e) => { console.error(e); process.exit(1); });
908	}
909	
910	export { parseWorkItemTitle };
911

