        await strikeClaim(api, gh, repo, claim);
        await swapStatus(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, BLOCKED);
        log(`- #${item.number} ${id}: requeued until ${result.requeue.until}${result.requeue.reason ? ` — ${result.requeue.reason}` : ''}`);
