9	// diff sat inside the policy is the policy engine's verdict (merge-policy.mjs),
10	// made where the tree is readable — the landing lane's CLI and the
11	// automerge-policy-scope work check.
12	//
13	// Pushes to non-default branches (e.g. the conversation-logs prune) are outside
14	// the PR taxonomy (DESIGN §1) and are not judged here — the caller passes only
15	// what the task did to PULL REQUESTS.
16	
17	import { LEGACY_OUTCOMES, canonicalOutcome, opensPullRequest } from './task-contract.mjs';
18	import { normalizePolicy } from './merge-policy.mjs';
19	
20	// Verify what a task actually did against its declared ceiling.
21	//   outcome      — the declared outcome (any of `OUTCOMES`; the retired `none`,
22	//                  `pr`, `open-pr` and `merged-pr` are judged as what they
23	//                  normalize to, so a fielded caller passing a raw declaration
24	//                  stays correct)
25	//   automerge — the declared merge policy; absent reads as 'nothing', and an
26	//                  unparsable one the same — a permission that cannot be read
27	//                  was never granted
28	//   openedPr     — did the run open a pull request?
29	//   mergedPr     — did the run merge (or arm auto-merge on) a pull request?
30	// Returns { ok, violation } — violation is null when within the ceiling.
31	export function verifyOutcome({ outcome, automerge, openedPr = false, mergedPr = false }) {
32	  const legacyPolicy = LEGACY_OUTCOMES[outcome];
33	  const ceiling = canonicalOutcome(outcome);
34	  const policy = automerge ?? legacyPolicy ?? 'nothing';
35	  if (!ceiling) {
36	    return { ok: false, violation: `unknown outcome ceiling "${outcome}"` };
37	  }
38	  // Merging implies a PR exists; treat a merge as also having opened one so a
39	  // caller that only reports mergedPr is still judged correctly.
40	  const opened = openedPr || mergedPr;
41	
42	  if (!opensPullRequest(ceiling) && opened) {
43	    return { ok: false, violation: `a "${ceiling}" task must not open or merge a pull request` };
44	  }
45	  if (mergedPr) {
46	    const norm = normalizePolicy(policy);
47	    if (norm.kind === 'nothing' || norm.kind === 'invalid') {
48	      return { ok: false, violation: 'a task whose automerge authorizes nothing must not merge a pull request' };
49	    }
50	  }
51	  return { ok: true, violation: null };
52	}

